alpha.script:
'use strict';

/**
 * @param {Number} value (for property 'alpha')
 */
export function update(value) {
	return value;
}

/**
 * Switches the wallpaper back to Yan Lab through the user shortcut 'yanlab'.
 * @param {CursorEvent} event
 */
export function cursorClick(event) {
	engine.openUserShortcut('yanlab');
}
